msg.allEntries = msg.payload;
msg.processedEntries = [];
msg.currentIndex = 0;

return msg;

const entry = msg.allEntries[msg.currentIndex];

if (entry.files && entry.files.length > 0) {
    msg.currentEntry = entry;
    msg.filesToProcess = entry.files;
    msg.rayvnFileIds = [];
    msg.currentFileIndex = 0;
    return [msg, null];
} else {
    entry.rayvnFileIds = [];
    msg.processedEntries.push(entry);
    msg.currentIndex++;
    return [null, msg];
}

// Rydd opp fra forrige HTTP-request
delete msg.statusCode;
delete msg.headers;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete msg.responseCookies;
delete msg.payload;

const wasos_url = global.get("wasos_url");
const wasos_config = global.get("wasos_config");
const fileInfo = msg.filesToProcess[msg.currentFileIndex];

if (!fileInfo || !fileInfo.url) {
    node.warn("Fil mangler URL: " + JSON.stringify(fileInfo));
    msg.currentFileIndex++;
    if (msg.currentFileIndex >= msg.filesToProcess.length) {
        return [null, msg];
    }
    return [msg, null];
}

msg.currentFile = {
    filename: fileInfo.name || "unknown",
    extension: fileInfo.extension || (fileInfo.name ? fileInfo.name.split('.').pop() : "bin"),
    filetype: fileInfo.type || "application/octet-stream",
    size: fileInfo.size
};

msg.url = wasos_url + fileInfo.url;
msg.headers = { "x-api-key": wasos_config.api.key };

node.log("Henter fil fra WaSOS: " + msg.url);
return [msg, null];

const rayvn_config = global.get("rayvn_config");
const rayvn_url = global.get("rayvn_url");
const buffer = msg.payload;

if (!buffer || buffer.length === 0 || msg.statusCode !== 200) {
    node.warn("Kunne ikke hente fil fra WaSOS. Status: " + msg.statusCode);
    msg.currentFileIndex++;
    if (msg.currentFileIndex < msg.filesToProcess.length) {
        return [msg, null];
    } else {
        return [null, msg];
    }
}

node.log("Hentet fil fra WaSOS: " + buffer.length + " bytes");

// Bygg multipart/form-data
const boundary = "----ParatBridge" + Date.now() + Math.random().toString(36).substr(2);
const filename = msg.currentFile.filename;
const filetype = msg.currentFile.filetype;

const headerPart = 
    "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="file"; filename="' + filename + '"\r\n' +
    "Content-Type: " + filetype + "\r\n\r\n";

const footerPart = "\r\n--" + boundary + "--\r\n";

msg.payload = Buffer.concat([
    Buffer.from(headerPart),
    buffer,
    Buffer.from(footerPart)
]);

msg.url = rayvn_url + "/files";
msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key,
    "Content-Type": "multipart/form-data; boundary=" + boundary
};

node.log("Laster opp til Rayvn /files: " + filename);
return [msg, null];

const response = msg.payload;

node.log("Rayvn /files status: " + msg.statusCode);

if (msg.statusCode === 200 || msg.statusCode === 201) {
    let fileId;
    if (typeof response === "string") {
        try { fileId = JSON.parse(response).id; } catch(e) {}
    } else if (response) {
        fileId = response.id;
    }

    if (fileId) {
        msg.rayvnFileIds.push(fileId);
        node.log("SUCCESS: Rayvn fil-ID: " + fileId);
    } else {
        node.warn("Rayvn OK men ingen fil-ID i response: " + JSON.stringify(response).substring(0, 200));
    }
} else {
    node.warn("Rayvn upload feilet. Status: " + msg.statusCode);
}

msg.currentFileIndex++;
if (msg.currentFileIndex < msg.filesToProcess.length) {
    return [msg, null];
} else {
    return [null, msg];
}

const entry = msg.currentEntry;
entry.rayvnFileIds = msg.rayvnFileIds || [];

if (entry.rayvnFileIds.length > 0) {
    node.log("Entry med " + entry.rayvnFileIds.length + " bilde(r) klar for Rayvn");
} else if (entry.files && entry.files.length > 0) {
    node.warn("Entry hadde " + entry.files.length + " fil(er) men ingen ble lastet opp");
}

msg.processedEntries.push(entry);
msg.currentIndex++;

// Rydd opp
delete msg.currentEntry;
delete msg.filesToProcess;
delete msg.rayvnFileIds;
delete msg.currentFileIndex;
delete msg.currentFile;

return msg;

if (msg.currentIndex < msg.allEntries.length) {
    return [msg, null];
} else {
    msg.payload = msg.processedEntries;
    delete msg.allEntries;
    delete msg.processedEntries;
    delete msg.currentIndex;
    node.log("Image processing ferdig: " + msg.payload.length + " entries");
    return [null, msg];
}
